import math

def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_coolness_condition(n):
    sum_n = n * (n + 1) // 2
    is_sq = is_perfect_square(sum_n)
    return is_sq, sum_n

numbers_to_check = [1680, 1682, 2029, 2031]
results = {}

print("--- Checking Necessary Condition (S_n must NOT be a square) ---")
for n in numbers_to_check:
    is_sq, sum_n = check_coolness_condition(n)
    is_cool_hypothesis = not is_sq
    results[n] = (is_sq, sum_n, is_cool_hypothesis)
    print(f"n={n}: S_n = {sum_n}. Is perfect square? {is_sq}. Predicted Coolness: {is_cool_hypothesis}")

print("\nSummary of findings:")
for n, (is_sq, _, predicted) in results.items():
    print(f"n={n}: S_n is {'a' if is_sq else 'not a'} perfect square. Hypothesis predicts coolness: {predicted}")
